        )

    totals = {
        "identities": 0,
        "baseline_evaluated": 0,
        "baseline_hit": 0,
        "baseline_missed": 0,
        "observation_evaluated": 0,
        "observation_hit": 0,
        "observation_missed": 0,
    }
